import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/widgets.dart';

final Uint8List kGebzeRobotFallbackBytes = base64Decode(
  '',
);

Widget buildGebzeRobotImage({
  double? width,
  double? height,
  BoxFit fit = BoxFit.contain,
  Alignment alignment = Alignment.center,
  FilterQuality filterQuality = FilterQuality.medium,
}) {
  return Image.asset(
    'assets/images/gebzechatbot.png',
    width: width,
    height: height,
    fit: fit,
    alignment: alignment,
    filterQuality: filterQuality,
    gaplessPlayback: true,
    errorBuilder: (context, error, stackTrace) {
      return Image.memory(
        kGebzeRobotFallbackBytes,
        width: width,
        height: height,
        fit: fit,
        alignment: alignment,
        filterQuality: filterQuality,
        gaplessPlayback: true,
      );
    },
  );
}

MemoryImage get kGebzeRobotMemoryImage => MemoryImage(kGebzeRobotFallbackBytes);
